def max_volume(s):
    """Write a python function to find the maximum volume of a cuboid with given sum of sides.

    The side lengths are positive integers summing to ``s``. For a fixed
    number of sides, the product is maximized when the side lengths are
    as equal as possible, so the sides differ by at most one.
    Returns 0 when ``s`` is too small for three positive integer sides.
    """
    if isinstance(s, float) and s.is_integer():
        s = int(s)
    if not isinstance(s, int):
        raise TypeError("s must be an integer")
    base, remainder = divmod(s, 3)
    # ``remainder`` sides have length base + 1 and the rest have length base.
    # When ``s`` is too small for three positive sides this product is
    # not positive, so flooring the result at zero covers that case
    # without a separate value-based branch.
    return max(0, (base + 1) ** remainder * base ** (3 - remainder))
